function person(e,i){if(e.empty)return;const g=new T.Group(),skin=new T.MeshStandardMaterial({color:[0xd4ad91,0xb9866b,0xc9987a,0xdfb69b,0xb88366,0xd9aa86,0xc08c72,0xe0b799][i],roughness:.5}),suit=new T.MeshStandardMaterial({color:[0x31445b,0x405447,0x3b4660,0x55415f,0x4b382f,0x2e4a4d,0x533640,0x40503a][i],roughness:.32}),pants=new T.MeshStandardMaterial({color:0x242b33,roughness:.42});const torso=add(new T.CapsuleGeometry(.26,.72,7,16),suit,g,0,1.23,0);torso.scale.set(1.06,1,.72);add(new T.SphereGeometry(.25,26,20),skin,g,0,1.88,0);add(new T.SphereGeometry(.255,22,10,0,Math.PI*2,0,Math.PI*.48),M.black,g,0,1.94,0);const arms=[];[-1,1].forEach(s=>{const a=add(new T.CapsuleGeometry(.07,.48,5,10),suit,g,s*.32,1.25,0);arms.push(a);add(new T.CapsuleGeometry(.08,.64,5,10),pants,g,s*.12,.42,0);box(g,.17,.09,.34,pants,s*.12,.08,-.07)});const [x,z]=slots[i];g.position.set(x-.15,.12,z-.82);g.scale.setScalar(1.2);g.traverse(o=>{if(o.isMesh)mark(o,{type:'employee',id:e.id,index:i})});S.add(g);agents.set(e.id,{g,home:g.position.clone(),moving:false,path:[],seg:0,t:0,index:i,arms,mode:'WORKING'});const el=document.createElement('div');el.className='label active';el.innerHTML='<b>'+e.name+'</b><small>'+e.role+'</small>';document.getElementById('hqv15').appendChild(el);labels.push({el,g,id:e.id})}E.forEach(person);
